    private bool _saving;
    private string? _statusMessage;
    private bool _isSuccess;

    protected override async Task OnInitializedAsync()
    {
        var profile = await SettingsService.GetProfileAsync();
        ApplyProfile(profile);
        SnapshotSavedState();
        _loading = false;
    }

    private void ApplyProfile(Models.UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private void SnapshotSavedState()
    {
        _savedDisplayName = _displayName;
        _savedEmail = _email;
        _savedAvatarUrl = _avatarUrl;
        _savedBio = _bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _statusMessage = null;
        try
        {
            var profile = new Models.UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(profile);
            SnapshotSavedState();
            _statusMessage = "Profile saved successfully!";
            _isSuccess = true;
        }
        catch (Exception ex)
        {
            _statusMessage = $"Error saving profile: {ex.Message}";
            _isSuccess = false;
        }
        finally
        {
            _saving = false;
        }
    }

    private void DiscardChanges()
    {
        _displayName = _savedDisplayName;
        _email = _savedEmail;
        _avatarUrl = _savedAvatarUrl;
        _bio = _savedBio;
        _statusMessage = null;
    }
}

